function canonicalize(value) {
  let s = String(value || '').trim()
    .replace(/^[<"'(\[]+|[>"')\],;]+$/g, '')
    .replace(/[.,;]+$/, '');

  const m = s.match(
    /^(https?):\/\/([^\/?#]+)(\/[^?#]*)?(\?[^#]*)?(?:#.*)?$/i
  );

  if (!m) {
    throw new Error('Ungueltige URL: ' + s);
  }

  let host = m[2].toLowerCase()
    .replace(/^www\./, '')
    .replace(/:443$|:80$/, '');

  if (
    host.includes('@') ||
    host.includes(':') ||
    /^localhost$|^127\.|^10\.|^192\.168\.|^169\.254\.|^172\.(1[6-9]|2\d|3[01])\./.test(host)
  ) {
    throw new Error('Keine oeffentlich erreichbare URL: ' + s);
  }

  let path = (m[3] || '/')
    .replace(/\/{2,}/g, '/')
    .replace(/\/$/, '') || '/';

  if (host === 'linkedin.com') {
    const li = path.match(
      /^\/jobs\/view\/(?:[^/]*-)?(\d{8,})$/i
    );
    if (li) path = '/jobs/view/' + li[1];
  }

  const idKeys = new Set([
    'job', 'jobid', 'job_id', 'jobsid', 'jid',
    'gh_jid', 'id', 'req', 'reqid',
    'requisition', 'requisitionid', 'jobcode',
    'jobreference', 'jobnumber', 'postingid',
    'jobpostingid', 'vacancyid', 'vacancy',
    'positionid', 'offerid', 'reference',
    'referencenumber', 'jk', 'j', 'r',
    'currentjobid', 'externalid',
    'jobidentifier', 'jobposting'
  ]);

  const tracking =
    /^(utm_|mtm_|pk_|hsa_|fbclid$|gclid$|gbraid$|wbraid$|msclkid$|mc_cid$|mc_eid$|yclid$|li_fat_id$|trk$|tracking|trackingid$|clickid$|click_id$|adid$|adgroup|campaign|campaignid$|source$|src$|ref$|referrer$|referral$|from$|origin$|via$|share$|shared$|mkt_tok$|_ga$|_gl$|igshid$|srsltid$|vero_|oly_|twclid$|rdt_cid$|utm)/i;

  const generic =
    /^(|jobs?|job-details?|job-search|search|apply|positions?|openings?|vacanc(?:y|ies)|careers?|view|details?|listing|index\.html)$/i.test(
      path.split('/').pop() || ''
    );

  const kept = [];
  const q = (m[4] || '').slice(1);

  if (q) {
    for (const p of q.split('&')) {
      if (!p) continue;

      const eq = p.indexOf('=');
      const encodedKey = eq >= 0 ? p.slice(0, eq) : p;
      const valuePart = eq >= 0 ? p.slice(eq + 1) : '';

      let key;
      try {
        key = decodeURIComponent(
          encodedKey.replace(/\+/g, ' ')
        ).toLowerCase();
      } catch {
        key = encodedKey.toLowerCase();
      }

      if (tracking.test(key)) continue;

      if (idKeys.has(key) || generic) {
        kept.push([key, encodedKey, valuePart]);
      }
    }
  }

  kept.sort(
    (a, b) =>
      a[0].localeCompare(b[0]) ||
      a[2].localeCompare(b[2])
  );

  const roleFragment = host === 'square8.ai' && path === '/careers.html' && /#[a-z0-9-]+$/i.test(s) ? '#' + s.split('#').pop().toLowerCase() : '';
  return 'https://' + host + path +
    (kept.length ? '?' + kept.map(x => x[1] + '=' + x[2]).join('&') : '') + roleFragment;
}

// Gemeinsame URL-Liste von Formular UND Tagesscan.
const candidates =
  $('Stellen-URLs vereinheitlichen')
    .first().json.candidateUrls || [];

const lines = candidates.map(c => ({
  url: String(c.url || '').trim(),
  listingText: String(c.listingText || ''),
  sourceFirma: String(c.sourceFirma || ''),
  sourceJobtitel: String(c.sourceJobtitel || '')
}));

// Bereits gespeicherte Stellen aus Google Sheets.
const existing = new Map();

for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.Link) continue;

  try {
    const key = canonicalize(r.Link);
    if (!existing.has(key)) {
      existing.set(key, r);
    }
  } catch (e) {
    // Alte fehlerhafte Links ignorieren.
  }
}

const seen = new Set();
const result = [];
let skipped = 0;

for (const candidate of lines) {
  const rawUrl = candidate.url;
  const key = canonicalize(rawUrl);

  if (seen.has(key)) {
    skipped++;
    continue;
  }

  seen.add(key);

  const old = existing.get(key) || null;

  const currentFirma =
    String(old?.Firma || '').trim();

  const firmaLooksLikeProse =
    currentFirma.length > 95 ||
    currentFirma.split(/\s+/).length > 12;

  const retry = old && (
    /^\s*\u26A0/.test(
      String(old.Bemerkungen || '')
    ) ||
    !String(old.Jobtitel || '').trim() ||
    firmaLooksLikeProse
  );

  if (old && !retry) {
    skipped++;
    continue;
  }

  result.push({
    json: {
      originalUrl: rawUrl,
      link: old ? String(old.Link) : key,
      existing: old || {},
      retry: Boolean(retry),
      listingText: candidate.listingText,
      sourceFirma: candidate.sourceFirma,
      sourceJobtitel: candidate.sourceJobtitel
    }
  });
}

console.log(
  'Eingereicht: ' + lines.length +
  ', Verarbeitung: ' + result.length +
  ', Duplikate/Bestand: ' + skipped
);

return result;

