const source = $('Neue Links herausfiltern').all();
const incoming = $input.all();

function decoded(s) {
  return String(s || '')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&nbsp;|&#160;/gi, ' ').replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"').replace(/&apos;|&#39;/gi, "'")
    .replace(/&auml;/gi, 'ä').replace(/&ouml;/gi, 'ö').replace(/&uuml;/gi, 'ü')
    .replace(/&Auml;/g, 'Ä').replace(/&Ouml;/g, 'Ö').replace(/&Uuml;/g, 'Ü')
    .replace(/&szlig;/gi, 'ss').replace(/&rsquo;/gi, '’').replace(/&ndash;/gi, '–');
}
function plain(markup) {
  return decoded(String(markup || '')
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<\/(?:p|div|li|ul|ol|h[1-6]|section|article)>/gi, '\n')
    .replace(/<br\b[^>]*\/?>/gi, '\n')
    .replace(/<[^>]*>/g, ' ')
  ).replace(/[ \t]+/g, ' ').replace(/\n[ \t]*/g, '\n')
   .replace(/\n{3,}/g, '\n\n').trim();
}

return incoming.map((item, i) => {
  const pair = item.pairedItem;
  const originIndex = Array.isArray(pair) ? pair[0]?.item : pair?.item;
  const base = source[Number.isInteger(originIndex) ? originIndex : i]?.json;
  if (!base) throw new Error('Zuordnung URL zu HTTP-Antwort fehlgeschlagen (Item ' + i + ').');

  const x = item.json || {};
  const status = Number(x.statusCode || 0);
  const errorText = x.error
    ? (typeof x.error === 'string' ? x.error : JSON.stringify(x.error)) : '';
  const raw = typeof x.body === 'string' ? x.body :
    typeof x.data === 'string' ? x.data : typeof x.body === 'object' ? JSON.stringify(x.body) : '';
  const originalUrl = String(base.originalUrl || '');
  let providerText = '';
  let providerTitle = '';
  let sourceMethod = '';
  let providerIssue = '';

  const listing = String(base.listingText || '').trim();
  const listingBody = listing.match(/(?:^|\n)Ausschreibungstext:\s*([\s\S]+)/i);
  if (listingBody && listingBody[1].trim().length >= 350 &&
      (base.sourceJobtitel || /Stellentitel:/.test(listing))) {
    providerText = listing.slice(0, 27000);
    providerTitle = String(base.sourceJobtitel || '');
    sourceMethod = 'official_ats_scanner_listing';
  } else {
    const gh = originalUrl.match(/^https?:\/\/(?:job-boards|boards)\.greenhouse\.io\/([a-z0-9_-]+)\/jobs\/([0-9]+)/i);
    const oracle = originalUrl.match(/^https?:\/\/([a-z0-9.-]+\.oraclecloud\.com)\/hcmUI\/CandidateExperience\/[^/]+\/sites\/([a-z0-9_-]+)\/job\/([0-9]+)/i);
    const workable = originalUrl.match(/^https?:\/\/apply\.workable\.com\/([a-z0-9_-]+)\/j\/([a-z0-9]{8,20})\/?$/i);
    if (gh || oracle || workable) {
      try {
        const data = JSON.parse(raw);
        if (gh) {
          if (String(data?.id || '') !== gh[2]) throw new Error('Greenhouse-ID stimmt nicht mit URL ueberein.');
          const description = plain(data?.content);
          if (!data?.title || description.length < 350) throw new Error('Kein vollstaendiger Greenhouse-Originaltext.');
          providerTitle = String(data.title);
          providerText = 'Firma/Board: ' + gh[1] + '\nStellentitel: ' + data.title +
            '\nArbeitsort: ' + (data.location?.name || '') +
            '\nOriginal-Stellenbeschreibung:\n' + description;
          sourceMethod = 'greenhouse_public_jobs_api';
        } else if (oracle) {
          const job = Array.isArray(data?.items) ? data.items[0] : null;
          const description = plain(job?.ExternalDescriptionStr || job?.ExternalDescriptionHTML || job?.ShortDescriptionStr);
          const tasks = plain(job?.ExternalResponsibilitiesStr || job?.ExternalRespHTML);
          const requirements = plain(job?.ExternalQualificationsStr || job?.ExternalQualHTML);
          if (!job?.Title || (description.length + tasks.length + requirements.length < 450) ||
            !(requirements.length > 100 || /dein profil|your profile|requirements|qualifikationen|anforderungen/i.test(description))) {
            throw new Error('Oracle-API: Titel oder Aufgaben/Anforderungen fehlen.');
          }
          providerTitle = String(job.Title);
          providerText = 'Stellentitel: ' + job.Title + '\nArbeitsort: ' + (job.PrimaryLocation || '') +
            '\nFirma: ' + (oracle[1].toLowerCase() === 'iaaras.fa.ocs.oraclecloud.com' ? 'ELCA / ELCA-Gruppe' : 'Laut Oracle-Stellenportal') +
            '\nStellenbeschreibung:\n' + description + '\nAufgaben:\n' + tasks +
            '\nAnforderungen:\n' + requirements;
          sourceMethod = 'oracle_candidate_experience_api';
        } else if (workable) {
          const job = Array.isArray(data?.jobs)
            ? data.jobs.find(j => String(j?.shortcode || '').toUpperCase() === workable[2].toUpperCase())
            : null;
          const description = plain(job?.full_description || [
            job?.description || '', job?.requirements || '', job?.benefits || ''
          ].filter(Boolean).join('\n\n'));
          if (!job?.title || description.length < 350) throw new Error('Workable-ID nicht gefunden oder Text unvollstaendig.');
          providerTitle = String(job.title);
          providerText = 'Firma: ' + (data.name || workable[1]) + '\nStellentitel: ' + job.title +
            '\nArbeitsort: ' + [job.city, job.country].filter(Boolean).join(', ') +
            '\nOriginal-Stellenbeschreibung:\n' + description;
          sourceMethod = 'workable_public_widget_api';
        }
      } catch (e) {
        providerIssue = String(e?.message || e).slice(0, 170);
      }
    }
  }

  const ldjson = [];
  const re = /<script\b[^>]*type\s*=\s*["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = re.exec(raw)) && ldjson.length < 10) {
    const block = decoded(m[1]).trim();
    if (block) ldjson.push(block.slice(0, 15000));
  }
  const headTitle = decoded((raw.match(/<title\b[^>]*>([\s\S]*?)<\/title>/i) || [,''])[1])
    .replace(/\s+/g, ' ').trim();
  const visible = plain(raw.replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' '));

  let fetchIssue = '';
  if (errorText) fetchIssue = 'HTTP-Fehler: ' + errorText.slice(0, 180);
  else if (status && (status < 200 || status >= 300)) fetchIssue = 'HTTP-Status ' + status;
  else if (!raw || (visible.length < 160 && ldjson.join('').length < 160))
    fetchIssue = 'Keine brauchbare Stellenbeschreibung (ggf. Login oder JavaScript-Sperre).';
  else if (/access denied|verify you are human|captcha|checking your browser|cloudflare challenge/i.test(headTitle))
    fetchIssue = 'Seite blockiert automatisches Lesen.';

  if (providerText) {
    fetchIssue = ''; // Authentischer Originaltext ist auch bei HTTP-Fehler der Bewerbungsseite gueltig.
  } else if (providerIssue) {
    fetchIssue = providerIssue; // Keine API-JSON-Antwort als vermeintlichen Stellentext durchreichen.
  }
  const sourceText = providerText ||
    ('HTML-Titel: ' + headTitle + '\nJSON-LD:\n' + ldjson.join('\n') +
    '\nSichtbarer Text:\n' + visible.slice(0, 22000)).slice(0, 35000);

  return {json: {
    ...base,
    fetchIssue,
    httpStatus: status || 'unbekannt',
    pageTitle: (providerTitle || headTitle).slice(0, 250),
    sourceMethod: sourceMethod || 'webpage_html',
    sourceText: sourceText.slice(0, 35000)
  }, pairedItem: {item: i}};
});

