const prepared = $('Webinhalt vorbereiten').all();
const results = $input.all();
const out = [];
for (let i = 0; i < results.length; i++) {
  const pair = results[i].pairedItem;
  const pIndex = (Array.isArray(pair) ? pair[0]?.item : pair?.item);
  const p = prepared[Number.isInteger(pIndex) ? pIndex : i]?.json;
  if (!p) throw new Error('KI-Antwort kann keiner URL zugeordnet werden (Item ' + i + ').');
  const res = results[i].json || {};
  const apiStatus = Number(res.statusCode || 0);
  const data = res.body || res;
  let parsed = {};
  let parseIssue = '';
  try {
    const content = data?.choices?.[0]?.message?.content;
    parsed = typeof content === 'string' ? JSON.parse(content) : (content || {});
  } catch (e) { parseIssue = 'KI-Ergebnis nicht als JSON lesbar'; }
  const cell = x => String(x ?? '').trim().slice(0, 25000);
  const old = p.existing || {};
  const valid = !p.fetchIssue && !res.error && (!apiStatus || apiStatus === 200)
    && parsed.ok === true && cell(parsed.firma) && cell(parsed.jobtitel)
    && cell(parsed.jobbeschreibung) && cell(parsed.anforderungen);
  let notice = '';
  if (!valid) {
    const detail = p.fetchIssue || (apiStatus && apiStatus !== 200 ? 'OpenAI-HTTP-Status ' + apiStatus : '') || parseIssue || cell(parsed.hinweis)
      || (res.error ? JSON.stringify(res.error).slice(0, 170) : 'Beschreibung nicht vollstaendig ermittelbar');
    notice = '\u26A0\uFE0F AUTOMATISCH PRUEFEN: ' + detail.slice(0, 240);
  }
  // Manuelle Einstufung und Bewerbungsstatus bleiben bei technischen Wiederholungen erhalten.
  const oldRemarks = cell(old.Bemerkungen);
  const remarks = valid ? (oldRemarks.startsWith('\u26A0') ? '' : oldRemarks)
    : notice + (oldRemarks && !oldRemarks.startsWith('\u26A0') ? ' | ' + oldRemarks : '');
  out.push({json: {
    Firma: valid ? cell(parsed.firma) : cell(old.Firma),
    Jobtitel: valid ? cell(parsed.jobtitel) : cell(old.Jobtitel),
    '\u00dcber die Firma': valid ? cell(parsed.ueber_die_firma) || 'Aus Stellenanzeige nicht ersichtlich' : cell(old['\u00dcber die Firma']),
    Jobbeschreibung: valid ? cell(parsed.jobbeschreibung) : cell(old.Jobbeschreibung),
    Anforderungen: valid ? cell(parsed.anforderungen) : cell(old.Anforderungen),
    'Einsch\u00e4tzung Stephan': cell(old['Einsch\u00e4tzung Stephan']),
    Beworben: cell(old.Beworben) || 'Nein',
    Bemerkungen: remarks,
    Link: p.link
  }, pairedItem: {item: i}});
}
return out;

// Beiden Eingangswegen dasselbe Format geben: { candidateUrls: [...] }.
// Formular: eine Textarea mit beliebig vielen URLs.
// Taeglicher Scanner: candidateUrls inkl. optionalem offiziellen Beschreibungstext.
function readLinks(value) {
  const text = String(value ?? '')
    .replace(/&amp;/gi, '&')
    .replace(/\u200b/g, '')
    .replace(/[,;](?=https?:\/\/)/gi, '\n'); // auch mehrere URLs direkt hintereinander
  const urls = [];
  const lines = text.split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim().replace(/^[-*]\s*/, '');
    if (!line) continue;

    // Query-Parameter auf eigener Zeile: an letzte URL anhaengen.
    // Auch wichtige Stellen-IDs (z. B. jobId) bleiben erhalten.
    if (/^[?&]?[a-z][a-z0-9_.-]*=/i.test(line)) {
      if (!urls.length) throw new Error('Zeile ' + (i + 1) +
        ': URL-Parameter ohne vorherige URL: ' + line.slice(0, 80));
      const continuation = line.replace(/^[?&]+/, '').trim();
      const last = urls.length - 1;
      const sep = /[?&]$/.test(urls[last]) ? '' : (urls[last].includes('?') ? '&' : '?');
      urls[last] += sep + continuation;
      continue;
    }

    // Mehrere URLs auch auf derselben Zeile erkennen; Text wie "1." ignorieren.
    const found = Array.from(line.matchAll(/https?:\/\/[^\s<>\"'`]+/gi), x =>
      x[0].replace(/[),;\]]+$/, ''));
    if (!found.length) throw new Error('Zeile ' + (i + 1) +
      ': Keine gueltige Stellen-URL gefunden: ' + line.slice(0, 80));
    urls.push(...found);
  }
  if (!urls.length) throw new Error('Bitte mindestens eine vollstaendige Stellen-URL eingeben.');
  return urls;
}

const input = $input.first().json || {};
let candidates = [];
if (Array.isArray(input.candidateUrls)) {
  candidates = input.candidateUrls.map(c => ({
    url: String(c?.url || '').trim(),
    listingText: String(c?.listingText || '').slice(0, 22000),
    sourceFirma: String(c?.sourceFirma || ''),
    sourceJobtitel: String(c?.sourceJobtitel || '')
  })).filter(c => c.url);
} else if (typeof input.Urls === 'string') {
  candidates = readLinks(input.Urls).map(url => ({
    url, listingText: '', sourceFirma: '', sourceJobtitel: ''
  }));
} else {
  throw new Error('Kein erkanntes Eingabeformat: Formularfeld Urls oder candidateUrls erwartet.');
}
console.log('Eingang: ' + candidates.length + ' Stellen-URLs');
return [{json: {candidateUrls: candidates}}];

// n8n Code node: Run Once for Each Item.
// Eingabe: eine Zeile aus dem Tab "Firmenquellen".
// Ausgabe: { urls: [{url,listingText,sourceFirma,sourceJobtitel}], report: {...} }.
const source = $json || {};
const firma = String(source.Firma || '').trim();
const karriereseite = String(source.Karriereseite || '').trim();
const typEingabe = String(source.Typ || 'Auto').trim();
const kennung = String(source['Kennung (falls nötig)'] || '').trim();
const aktiv = /^(ja|yes|true|1|aktiv)$/i.test(String(source.Aktiv || '').trim());
const now = new Date().toISOString();
const report = {
  Zeitpunkt: now,
  Firma: firma,
  Karriereseite: karriereseite,
  Typ: typEingabe || 'Auto',
  'Gefundene Jobs': 0,
  Status: 'OK',
  Hinweis: ''
};
let urls = [];
if (!aktiv) {
  report.Status = 'INAKTIV';
  return { json: { urls, report } };
}

const decode = value => String(value || '')
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'");
const plain = value => decode(decode(String(value || ''))
  .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
